BEGIN;

UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"gcp-pca-q1": {"why_asked": "「世界規模」「強整合性」「水平スケール」の3条件が揃うのはPCA試験の定番パターンで、NoSQLは分散できるから世界規模に強いと短絡したり、リードレプリカで読み取りを分散すれば整合性の問題は起きないと誤解したりする受験者をふるい落とす狙いがある。"}, "gcp-pca-q2": {"why_asked": "「大量データ」という言葉だけでBigQueryに飛びつく誤答が起きやすい。分析（まとめて集計）と運用（1件をミリ秒で返す）はまったく別の負荷特性であり、書き込みの規模と読み出しの形の両方から絞り込めるかが問われる。"}, "gcp-pca-q3": {"why_asked": "Dataprocでも同じ分析はできてしまうため紛らわしいが、「クラスタという管理対象が残るかどうか」が分かれ目になる。サーバーレスの価値を、機能の可否ではなく運用負荷とコスト構造で説明できるかが試される。"}, "gcp-pca-q4": {"why_asked": "読み取り負荷が高いと聞くとリードレプリカを反射的に選びがちだが、原因が「同じデータへの参照の集中」であれば効果が薄い。ボトルネックの正体（多様なクエリの分散か、同一クエリの重複か）を見極めてから手段を選べるかが問われる。"}, "gcp-pca-q5": {"why_asked": "「監査や係争に備えたい」という言葉に引っ張られてNearlineやStandardのような安全側のクラスを選びがちだが、判断基準は実績アクセス頻度だけである。慎重さとコスト最小化の要件がぶつかったとき、感覚ではなく数字で決められるかが試される。"}, "gcp-pca-q6": {"why_asked": "「コンテナだからGKE」という短絡が典型的な誤答で、Pod数を0にできてもノードという土台のVMは動き続けコストが残ることまで見落としやすい。ゼロスケールが本当にどの層まで及ぶかを追えるかが問われる。"}, "gcp-pca-q7": {"why_asked": "PCA試験ではコンテナ化やサーバーレス化のような「クラウドらしい」選択肢が正解に見えやすい設計になっているが、この問題は期限と改修余力という制約から逆算すると近代化を選べないという、優先順位の判断力を試している。"}, "gcp-pca-q8": {"why_asked": "過剰設計はPCA試験の典型的な誤答パターンで、Cloud Spannerのような高機能なサービスほど「安全そうだから」という理由で選ばれがちである。要件に書かれていない世界規模の分散を勝手に足さず、規模に見合った選択ができるかが問われる。"}, "gcp-pca-q9": {"why_asked": "オフライン保持や変更検知は他のデータベースでも自作すれば実現できてしまうため、「作れるか」ではなく「標準機能として備えているか」で選べるかが問われる。モバイル特有の2要件がセットで出たときにFirestoreへ直結できるかがカギ。"}, "gcp-pca-q10": {"why_asked": "リージョンごとにロードバランサを置いてDNSで振り分ける構成は一見「最寄りへ案内する」要件を満たしているように見えるが、単一のグローバルIPという条件を見落としやすい。L4かL7か、グローバルかリージョンかという2軸を同時に判断できるかが試される。"}, "gcp-pca-q11": {"why_asked": "再試行やインスタンス増強は「詰まりを緩和する」対症療法に見えて、同期呼び出しという構造自体は変えられない。障害の原因が構造にあるとき、パラメータ調整ではなく構造そのものを変える判断ができるかが問われる。"}, "gcp-pca-q12": {"why_asked": "Storage Transfer Serviceや並列アップロードは「データ転送の手段」として名前は挙がるが、回線帯域という物理的な上限は工夫では超えられない。まず転送時間を計算し、ネットワーク経由が非現実的だと判断できるかが試される。"}, "gcp-pca-q13": {"why_asked": "HA VPNは冗長化されていて「安定していそう」に見えるため紛らわしいが、経路がインターネットのままである点は変わらない。帯域・遅延・経路（インターネットを通るか）という3条件を同時に満たせるかで、専用線と他の接続方式を切り分けられるかが問われる。"}, "gcp-pca-q14": {"why_asked": "「ネットワークの集約」と「部門ごとの自由な運用」という一見相反する2つの要求を同時に満たす構成を選べるかが試される。VPCピアリングやプロジェクト統合は片方の要求を犠牲にしてしまう点を見抜けるかがカギ。"}, "gcp-pca-q15": {"why_asked": "Cloud NATは「外部IPなしで外へ出る」ための機能として名前が挙がりやすいが、宛先がGoogleのサービスに限られる場合は不要な選択になる。到達したい相手がGoogleか、それ以外のインターネットかで手段を使い分けられるかが問われる。"}, "gcp-pca-q16": {"why_asked": "限定公開のGoogleアクセスと混同しやすい典型例で、宛先が外部の公開リポジトリである点を見落とすと誤答する。着信は遮断したまま外向きだけ許可するという要件を、外部IPを付けずに実現する手段を正確に選べるかが試される。"}, "gcp-pca-q17": {"why_asked": "負荷変動とゾーン障害という性質の異なる2つの問題が同時に出題されており、片方しか解決しない構成（マシンタイプ増強やゾーン単位のグループ）を選んでしまう誤りを誘発する。1つの構成で両方を満たせるかを見抜けるかが問われる。"}, "gcp-pca-q18": {"why_asked": "手順書の整備やレビュー体制の強化は「ちゃんとやっている感」があるため選ばれやすいが、実行主体が人である限り差異と履歴の欠如という根本原因は残る。表面的な対策と構造的な対策を見分けられるかが試される。"}, "gcp-pca-q19": {"why_asked": "マルチリージョンバケットは「複数リージョンに複製される」という説明だけを読むとCDNと混同しやすいが、目的は耐久性であって配信の高速化ではない。遅さの原因が処理能力か物理的な距離かを切り分けられるかが問われる。"}, "gcp-pca-q20": {"why_asked": "HA VPNのような接続方式は「つながっているから同じ」に見えるが、ゲートウェイという中継装置を経由する分だけ帯域と遅延で不利になる。IP範囲が重複していないという条件が、より軽量な接続方式を選べる合図だと読めるかが試される。"}, "gcp-pca-q21": {"why_asked": "IAMと組織のポリシーはどちらも組織階層に沿って設定できるため役割を取り違えやすく、この試験では両者の説明を意図的に入れ替えた紛らわしい選択肢が頻出する。主語が「人（権限）」か「構成（制約）」かで機械的に仕分けられるかが問われる。"}, "gcp-pca-q22": {"why_asked": "デフォルトの暗号化も「暗号化されている」という事実は満たしているため紛らわしいが、要件は暗号化の有無ではなく鍵の管理主体である。何が問われているかを正確に読み取れるかが試される。"}, "gcp-pca-q23": {"why_asked": "環境変数への注入や暗号化ファイルの共有は「平文で置かない」という表面的な要件は満たすが、取得履歴やローテーションまでは備えていない。要求されている性質を1つずつ照合し、抜けを見抜けるかが問われる。"}, "gcp-pca-q24": {"why_asked": "セキュリティの懸念に対してはIAM権限をさらに絞る発想が反射的に出やすいが、この問題の前提は「正規の認証情報が盗まれる」ことであり、その場合IAMは正当なアクセスとして通してしまう。想定する脅威に対して有効な防御層を選べるかが試される。"}, "gcp-pca-q25": {"why_asked": "VPCファイアウォールも「防御」には違いないため紛らわしいが、IPとポートしか見ないためSQLインジェクションのようなHTTPの中身に潜む攻撃は判定できない。防御を置く位置（手前か後か）と見る深さ（L4かL7か）の両方で選べるかが問われる。"}, "gcp-pca-q26": {"why_asked": "Secret Managerへの保管や鍵の定期入れ替えは「鍵の管理を良くする」対策として妥当に見えるが、鍵という持ち出せるもの自体は残り続ける。問題の根を「鍵の扱い方」ではなく「鍵の存在そのもの」に見出せるかが試される。"}, "gcp-pca-q27": {"why_asked": "VPNの増強やIPの許可リストは「接続元」という同じ発想の延長線上にある解決策で、在宅勤務の拡大という前提のもとでは根本的に破綻する。信頼の根拠を場所からIDへ切り替える発想に転換できるかが問われる。"}, "gcp-pca-q28": {"why_asked": "承認プロセスの整備や都度付与の運用は最小権限の理念には沿うが、開発速度を落とさないという条件と両立しない。理念だけでなく現実の制約（速度）まで満たす設計を、実測データに基づいて選べるかが試される。"}, "gcp-pca-q29": {"why_asked": "管理アクティビティログは既定で有効なため「もう記録されている」と誤解しやすいが、データの読み取りは対象外である。何が既定で有効かという知識と、記録した証跡自体を守る発想の両方が問われる複合問題。"}, "gcp-pca-q30": {"why_asked": "確約利用割引もコスト削減の選択肢として名前が挙がるが、それは常時稼働する予測可能な負荷に向いた仕組みであり、中断してよいバッチ処理には別の割引が向く。ワークロードの性質（中断耐性の有無）から適切な割引制度を選び分けられるかが試される。"}, "gcp-pca-q31": {"why_asked": "Spot VMは大幅な割引という魅力があるため誤って選ばれやすいが、24時間365日の本番システムには適用できない。中断を許容できるかどうかという条件を確認せずに割引率だけで飛びつかないかが試される、q30と対になる問題。"}, "gcp-pca-q32": {"why_asked": "クエリ回数の制限やストレージの料金体系見直しは「コスト対策」として一見それらしいが、BigQueryの課金はスキャン量で決まるため的外れになる。費用の決まり方を正しく理解したうえで、絞り込み条件とデータ配置を一致させる設計に落とし込めるかが問われる。"}, "gcp-pca-q33": {"why_asked": "端末環境の統一や手順の標準化は改善策として妥当に見えるが、実行主体が人のままである限り差異と追跡不能という問題の根は残る。ビルド・保管・反映という3つの役割をそれぞれ専用のマネージドサービスへ置き換える発想ができるかが試される。"}, "gcp-pca-q34": {"why_asked": "監視とログ集約はどちらか一方だけを実装して満足しがちだが、この問題は「気づく」ことと「調べる」ことという別々の課題に対応している。両方が揃って初めて運用が回るという役割分担を理解しているかが問われる。"}, "gcp-pca-q35": {"why_asked": "BigQueryへの移行やDataflowへの書き換えは「クラウドらしい最終形」に見えて選ばれやすいが、200本以上のジョブを書き換える工数がないという制約と矛盾する。理想形と、制約下で現実的に選べる手段を区別できるかが試される。"}, "gcp-pca-q36": {"why_asked": "Dataprocでもストリーミングとバッチの両方を実装できてしまうため紛らわしいが、クラスタ管理が残る点と、別々に実装したロジックが将来食い違うリスクを見落としやすい。同一ロジックの再利用とサーバーレスという2つの制約を同時に満たせるかが試される。"}, "gcp-pca-q37": {"why_asked": "人員増強や手順書の精緻化は現場感覚として「まっとうな対応」に見えるが、サービスの成長に比例して増える作業には効かない。トイルを人で吸収するのではなく自動化で総量を減らすというSREの基本姿勢が身についているかが試される。"}, "gcp-pca-q38": {"why_asked": "作成日時の古さやラベルの欠如は「使われていなさそう」という直感には合うが、実際の使用状況とは無関係で、稼働中のリソースを誤って止める事故につながる。判断の根拠を勘や間接的な手がかりではなく実測データに置けるかが試される。"}, "gcp-pca-q39": {"why_asked": "Cloud Buildのトリガーやブルーグリーン切り替えでも段階的な反映の一部は再現できてしまうため紛らわしいが、カナリア（一部利用者への先行公開）までは自作が必要になる。3つの要件をすべて標準機能として持つサービスを見極められるかが問われる。"}, "gcp-pca-q40": {"why_asked": "手順書の整備や熟練者への属人化は一見統制が取れているように見えるが、実行主体が人である限り再現性と追跡可能性は保証できない。既存リソースへの日常操作という限定的なスコープに対して、フルのIaCではなくCLIスクリプト化がちょうど良い解だと判断できるかが試される。"}, "gcp-pca-q41": {"why_asked": "ラベルやネットワーク分離は「環境を分けている」ように見えるため紛らわしいが、権限と課金の境界にはならない。Google Cloudでは何が権限と課金の基本単位かという知識を、事故の再発防止という文脈で正しく適用できるかが問われる。"}, "gcp-pca-q42": {"why_asked": "ダンプ＆リストアやバックアップからの復元は移行手段として直感的だが、1.5TBの移動時間が停止時間の許容範囲を超えてしまう。停止時間がどの作業で発生するかを分解し、継続的レプリケーションで最小化できるかが試される。"}, "gcp-pca-q43": {"why_asked": "Cloud Storageへの保管でも権限制御はできてしまうため一見成立しそうだが、イメージの版管理や脆弱性スキャンという専用機能が欠ける。汎用のストレージと専用のレジストリの違いを、要件の細部から見抜けるかが問われる。"}, "gcp-pca-q44": {"why_asked": "バックアップ頻度を上げる発想は自然だが、取得間隔がそのままRPOの下限になるため「ほぼゼロ」には届かない。要件を「ほぼゼロ＝RPOが極小」と正しく翻訳し、継続的レプリケーションでなければ満たせないと判断できるかが試される。"}, "gcp-pca-q45": {"why_asked": "待機系への手動切り替えやスナップショットからの復元も「対策している」ように見えるが、検知や復元の時間だけ必ず停止が生じる。「継続する」という要件が「常時稼働している複数系統への分散」を意味すると理解できるかが問われる。"}, "gcp-pca-q46": {"why_asked": "スケジュールベースのスケーリングは一見合理的だが、速報の発生タイミングが予測できないという前提でははまらない。負荷変動が予測可能かどうかを見極めたうえで、指標に基づく自動追従を選べるかが試される。"}, "gcp-pca-q47": {"why_asked": "可用性100%の宣言やリリース回数の制限は一見厳格な統制に見えるが、定量的な判断基準にはならず対立を構造的には解決しない。SLOとエラーバジェットが、開発と運用の利害を1つの残高に変換して自動的に調停する仕組みだと理解できるかが試される。"}, "gcp-pca-q48": {"why_asked": "バージョニングやゾーンをまたぐ冗長化は「守られている」ように見えるが、対象範囲がリージョン内にとどまるためリージョン全体の喪失には耐えられない。想定する障害の範囲と対策の範囲を一致させられるかが問われる。"}, "gcp-pca-q49": {"why_asked": "根本原因の特定を先に行う姿勢は平時の開発では正しい態度だが、被害が進行中の障害対応では優先順位が逆転する。原因が未確定でも直前のリリースをロールバックして影響を止めるという、緩和優先のSREの原則を理解しているかが試される。"}, "gcp-pca-q50": {"why_asked": "CPUやメモリの使用率監視は「監視している」という点では妥当に見えるが、応答しないプロセスはむしろ使用率が低く推移するため検知できない。健全性の判定基準を、インスタンスの起動状態ではなくアプリケーションの実際の応答に置けるかが試される。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-pca')
  AND q.explanation_data IS NOT NULL;

COMMIT;
